// @match        https://space.bilibili.com/2068450020/?*
// @match        https://space.bilibili.com/2068450020/*
// @match        https://space.bilibili.com/2068450020/*?*
// @run-at       document-idle
// @grant        none
// @noframes
// ==/UserScript==
